function observeHomeArtistReveal(t){const e=t.querySelectorAll(".artist-card"),s=window.matchMedia&&window.matchMedia("(prefers-reduced-motion: reduce)").matches;if(!e.length)return;if(s||!("IntersectionObserver"in window))return void e.forEach(function(t){t.classList.add("artist-card--visible")});const n=new IntersectionObserver(function(t,e){t.forEach(function(t){if(!t.isIntersecting)return;const s=t.target,n=Number(s.dataset.revealIdx||0);s.style.transitionDelay=Math.min(70*n,280)+"ms",s.classList.add("artist-card--visible"),e.unobserve(s)})},{threshold:.12,rootMargin:"0px 0px -8% 0px"});e.forEach(function(t,e){t.dataset.revealIdx=String(e),n.observe(t)})}async function initHomeArtistsPreview(){const t=document.getElementById("homeArtistsGrid");if(t){t.innerHTML='<p class="muted">Loading artists...</p>';try{const e=await fetchArtistsFromSanity(3);if(!e||!e.length)return void(t.innerHTML='<p class="muted">No artists available.</p>');t.innerHTML=e.map(t=>{const e=t.slug||t._id,s=t.image?.asset?.url||null,n=s?"function"==typeof window.sanityImgUrl?window.sanityImgUrl(s,{w:560,h:700,fit:"crop",q:82}):s:"images/artists/placeholder.jpg";return`\n        <a class="artist-card"\n           href="artists/artist.html?artist=${encodeURIComponent(e)}">\n\n          <div class="artist-showcase-media">\n            <div class="artist-avatar"\n                 style="background-image:url('${n}')"></div>\n          </div>\n\n          <h3 class="artist-name">\n            <img src="images/icon.jpg" class="flag-icon" alt="">\n            <span>${t.name}</span>\n          </h3>\n\n          ${t.style?`<p class="artist-style">${t.style}</p>`:""}\n        </a>\n      `}).join(""),observeHomeArtistReveal(t)}catch(e){console.error("Failed to load artists on home page",e),t.innerHTML='<p class="muted">Failed to load artists.</p>'}}}"loading"===document.readyState?document.addEventListener("DOMContentLoaded",initHomeArtistsPreview):initHomeArtistsPreview();